private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int index = i;
    while (index < bb.limit()) {
        int b = bb.get(index++);
        if (b < 0) {
            // Invalid octet
            throw new IllegalArgumentException("Invalid octet: " + b);
        }
        if (b < 0x80) {
            // ASCII character
            sb.append((char) b);
        } else if (b < 0xC0) {
            // Continuation octet
            int c = b & 0x3F;
            if (c < 0x20) {
                // Invalid continuation octet
                throw new IllegalArgumentException("Invalid continuation octet: " + c);
            }
            sb.append((char) c);
        } else if (b < 0xE0) {
            // Two-byte sequence
            int c1 = b & 0x1F;
            int c2 = bb.get(index++);
            if (c2 < 0x80 || c2 > 0xBF) {
                // Invalid continuation octet
                throw new IllegalArgumentException("Invalid continuation octet: " + c2);
            }
            sb.append((char) (c1 << 6 | c2));
        } else if (b < 0xF0) {
            // Three-byte sequence
            int c1 = b & 0x0F;
            int c2 = bb.get(index++);
            int c3 = bb.get(index++);
            if (c2 < 0x80 || c2 > 0xBF || c3 < 0x80 || c3 > 0xBF) {
                // Invalid continuation octet
                throw new IllegalArgumentException("Invalid continuation octet: " + c2 + " or " + c3);
            }
            sb.append((char) (c1 << 12 | c2 << 6 | c3));
        } else if (b < 0xF8) {
            // Four-byte sequence
            int c1 = b & 0x07;
            int c2 = bb.get(index++);
            int c3 = bb.get(index++);
            int c4 = bb.get(index++);
            if (c2 < 0x80 || c2 > 0xBF || c3 < 0x80 || c3 > 0xBF || c4 < 0x80 || c4 > 0xBF) {
                // Invalid continuation octet
                throw new IllegalArgumentException("Invalid continuation octet: " + c2 + " or " + c3 + " or " + c4);
            }
            sb.append((char) (c1 << 18 | c2 << 12 | c3 << 6 | c4));
        } else {
            // Invalid octet
            throw new IllegalArgumentException("Invalid octet: " + b);
        }
    }
    return index;
}
