/**
 * Parses the conversion pattern and extracts the format specifiers.
 *
 * @param conversionPattern the conversion pattern to parse
 * @return a list of format specifiers
 */
private List<String> parseConversionPattern(String conversionPattern) {
    List<String> formatSpecifiers = new ArrayList<>();
    for (int i = 0; i < conversionPattern.length(); i++) {
        char c = conversionPattern.charAt(i);
        if (c == '%') {
            // Check if the next character is a format specifier
            if (i + 1 < conversionPattern.length()) {
                char nextChar = conversionPattern.charAt(i + 1);
                if (nextChar == 'd' || nextChar == 'i' || nextChar == 'o' || nextChar == 'u' || nextChar == 'x' || nextChar == 'X' || nextChar == 'e' || nextChar == 'E' || nextChar == 'f' || nextChar == 'g' || nextChar == 'G' || nextChar == 'a' || nextChar == 'A' || nextChar == 'c' || nextChar == 's') {
                    formatSpecifiers.add(String.valueOf(nextChar));
                }
            }
        }
    }
    return formatSpecifiers;
}

/**
 * Replaces the format specifiers with the corresponding values from the event.
 *
 * @param event the logging event
 * @param formatSpecifiers the list of format specifiers
 * @return the formatted string
 */
private String replaceFormatSpecifiers(LoggingEvent event, List<String> formatSpecifiers) {
    String formattedString = event.getMessage();
    for (String formatSpecifier : formatSpecifiers) {
        String replacement = getReplacement(event, formatSpecifier);
        formattedString = formattedString.replaceFirst("%" + formatSpecifier, replacement);
    }
    return formattedString;
}

/**
 * Gets the replacement for the given format specifier.
 *
 * @param event the logging event
 * @param formatSpecifier the format specifier
 * @return the replacement string
 */
private String getReplacement(LoggingEvent event, String formatSpecifier) {
    switch (formatSpecifier) {
        case "d":
            return String.valueOf(event.getTimeStamp());
        case "i":
            return String.valueOf(event.getThreadName());
        case "o":
            return String.valueOf(event.getLoggerName());
        case "u":
            return String.valueOf(event.getLevel());
        case "x":
            return String.valueOf(event.getNDC());
        case "X":
            return String.valueOf(event.getMDC());
        case "e":
            return String.valueOf(event.getThrowableStrRep());
        case "E":
            return String.valueOf(event.getThrowableInformation());
        case "f":
            return String.valueOf(event.getLocationInformation());
        case "g":
            return String.valueOf(event.getLogger());
        case "G":
            return String.valueOf(event.getMarker());
        case "a":
            return String.valueOf(event.getArgumentArray());
        case "s":
            return String.valueOf(event.getSource());
        default:
            return "";
    }
}

