public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
  // Step 1: Validate input
  if (graph == null) {
    throw new IllegalArgumentException("Graph cannot be null");
  }

  // Step 2: Create an empty mapping
  IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>();

  // Step 3: Iterate over the graph vertices and edges
  for (V vertex : graph.vertices()) {
    // Step 3a: Add the vertex to the mapping
    mapping.addVertex(vertex, vertex);

    // Step 3b: Iterate over the edges incident to the vertex
    for (E edge : graph.edges(vertex)) {
      // Step 3c: Add the edge to the mapping
      mapping.addEdge(edge, edge);
    }
  }

  // Step 4: Return the mapping
  return mapping;
}

