private static void deleteDirectory(File directory) throws IOException {
    if (!directory.exists()) {
        return;
    }
    File[] files = directory.listFiles();
    if (files == null) {
        throw new IOException("Failed to list files in directory: " + directory);
    }
    for (File file : files) {
        if (file.isDirectory()) {
            deleteDirectory(file);
        } else {
            file.delete();
        }
    }
    directory.delete();
}
