    if (size == 0) {
        return 0;
    }

    int prefixSize = computeRawVarint32Size(size);
    int totalSize = prefixSize + size;

    if (totalSize > buffer.capacity()) {
        throw new IOException("Buffer overflow: buffer capacity (" + buffer.capacity() + ") exceeded");
    }

    buffer.writeRawVarint32(size);
    schema.writeTo(message, buffer);

    return totalSize;
}

