/**
 * Follow the dayStep to re-format the time bucket literal long value. Such as, in dayStep == 11, 20000105 re-formatted time bucket is 20000101, 20000115 re-formatted time bucket is 20000112, 20000123 re-formatted time bucket is 20000123
 */
static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep < 1 || dayStep > 31) {
        throw new IllegalArgumentException("Invalid day step: " + dayStep);
    }
    if (timeBucket < 0) {
        throw new IllegalArgumentException("Invalid time bucket: " + timeBucket);
    }
    long days = timeBucket / 1000000;
    long remainder = timeBucket % 1000000;
    long newDays = days / dayStep * dayStep;
    long newRemainder = remainder % dayStep;
    return newDays * 1000000 + newRemainder;
}
