public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("Data cannot be null");
    }
    if (off < 0 || off >= b.length) {
        throw new IndexOutOfBoundsException("Offset must be non-negative and less than the length of the data");
    }
    if (len < 0 || len > b.length - off) {
        throw new IndexOutOfBoundsException("Length must be non-negative and less than the length of the data minus the offset");
    }
    if (len == 0) {
        return;
    }
    int bytesWritten = 0;
    while (bytesWritten < len) {
        int bytesToWrite = Math.min(len - bytesWritten, buffer.length - bufferPosition);
        System.arraycopy(b, off + bytesWritten, buffer, bufferPosition, bytesToWrite);
        bufferPosition += bytesToWrite;
        bytesWritten += bytesToWrite;
        if (bufferPosition == buffer.length) {
            flush();
        }
    }
}
